// Env is where an offline evaluation reads from.
type Env struct {
	// RepoDir is a fixture repo generated by internal/fixturegen and
	// PRsJSON the GitHub fixture (testdata/fixtures/prs.json).
	RepoDir string
	PRsJSON string
	// Recordings is testdata/recordings: Jev answers (jev/), embeddings
	// (embed/) and reviews (review/) are replayed from it, strictly.
	Recordings string
	// ReviewMisses lets a review request without a recording fail its row
	// (as `make demo` does) instead of failing the evaluation. Review
	// answers feed no metric (findings change hot-spot reasons only), so
	// the scores are the same; the board notes the misses.
	ReviewMisses bool
}

// Evaluate runs the full pipeline offline over the fixture PRs
// (pipelinetest.PRNumbers) and branches (pipelinetest.BranchRefs) the way
// the replay tests do — jev.Replay (strict), embed.Replay and one
// review.Replay per tier named by the fixture repo's configured models,
// default routing — and scores every truth against its item. Any Jev or
// embedding request without a recording, a failed stage, or a truth whose
// item the fixture run does not cover is an error.
func Evaluate(ctx context.Context, env Env, truths []Truth) (Board, error) {
	b, _, err := evaluate(ctx, env, truths, false)
	return b, err
}

// EvaluateExplain is Evaluate plus an Explain listing per truth, in truth
// order.
func EvaluateExplain(ctx context.Context, env Env, truths []Truth) (Board, []string, error) {
	return evaluate(ctx, env, truths, true)
}

func evaluate(ctx context.Context, env Env, truths []Truth, explain bool) (Board, []string, error) {
	outs, misses, err := runFixture(ctx, env)
	if err != nil {
		return Board{}, nil, err
	}
	rows := make([]Row, 0, len(truths))
	var notes []string
	for _, t := range truths {
		po, ok := outs[t.Item]
		if !ok {
			return Board{}, nil, fmt.Errorf("quality: %s: the fixture run has no such item (add it to pipelinetest.PRNumbers or BranchRefs)", t.Item)
		}
		o := Outcome{Units: po.Units, Agg: po.Agg, Labels: po.Labels}
		rows = append(rows, Score(t, o))
		if explain {
			notes = append(notes, Explain(t, o))
		}
	}
	b := NewBoard(rows)
	if misses > 0 {
		b.Notes = append(b.Notes, fmt.Sprintf("%d review requests had no recording and failed their row (allowed); review answers feed no metric", misses))
	}
	return b, notes, nil
}

// runFixture runs every fixture PR, then every fixture branch, in one
// environment, and returns the outcomes by item id and the number of
// tolerated review misses.
func runFixture(ctx context.Context, env Env) (map[string]pipelinetest.Outcome, int, error) {
	fast, deep, err := fixtureModels(ctx, env.RepoDir)
	if err != nil {
		return nil, 0, err
	}
	m := &misses{}
	jc := &jevMisses{next: &jev.Replay{Dir: filepath.Join(env.Recordings, "jev")}, m: m}
	emb := &embedMisses{next: &embed.Replay{Dir: filepath.Join(env.Recordings, "embed")}, m: m}
	revDir := filepath.Join(env.Recordings, "review")
	tiers := review.Tiers{
		Fast: &reviewMisses{next: &review.Replay{Name: fast, Dir: revDir, MissUnavailable: env.ReviewMisses}, m: m},
		Deep: &reviewMisses{next: &review.Replay{Name: deep, Dir: revDir, MissUnavailable: env.ReviewMisses}, m: m},
	}
	f, err := pipelinetest.Open(ctx, env.RepoDir, env.PRsJSON, jc, pipelinetest.WithEmbedder(emb), pipelinetest.WithReviewers(tiers))
	if err != nil {
		return nil, 0, fmt.Errorf("quality: open fixture: %w", err)
	}
	defer f.Close()
	prs, err := f.RunAll(ctx, pipeline.RunOptions{})
	if err != nil {
		return nil, 0, fmt.Errorf("quality: run fixture PRs: %w", err)
	}
	branches, err := f.RunBranches(ctx, pipeline.RunOptions{})
	if err != nil {
		return nil, 0, fmt.Errorf("quality: run fixture branches: %w", err)
	}
	out := make(map[string]pipelinetest.Outcome, len(prs)+len(branches))
	for _, o := range prs {
		out[o.Item.ID] = o
	}
	for _, o := range branches {
		out[o.Item.ID] = o
	}
	if err := m.check(env.ReviewMisses); err != nil {
		return nil, 0, err
	}
	if err := failedStages(out); err != nil {
		return nil, 0, err
	}
	return out, m.count("review"), nil
}

// fixtureModels returns the fast and deep model specs of the fixture
// repo's config (what the recorder records with and the replay tests name
// their review.Replay after).
func fixtureModels(ctx context.Context, repo string) (fast, deep string, err error) {
	g, err := gitx.Open(ctx, repo)
	if err != nil {
		return "", "", fmt.Errorf("quality: open fixture repo: %w", err)
	}
	gitDir, err := g.GitDir(ctx)
	if err != nil {
		return "", "", fmt.Errorf("quality: fixture git dir: %w", err)
	}
	c, err := config.Load([]string{filepath.Join(gitDir, "prt")})
	if err != nil {
		return "", "", fmt.Errorf("quality: fixture config: %w", err)
	}
	return c.Models.Fast, c.Models.Deep, nil
}

// failedStages returns an error naming every failed stage of every item.
func failedStages(outs map[string]pipelinetest.Outcome) error {
	ids := make([]string, 0, len(outs))
	for id := range outs {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	var ps []string
	for _, id := range ids {
		for _, rl := range outs[id].Failed() {
			ps = append(ps, fmt.Sprintf("%s: stage %s failed: %s", id, rl.Stage, rl.Err))
		}
	}
	if len(ps) > 0 {
		return fmt.Errorf("quality: fixture run failed:\n%s", strings.Join(ps, "\n"))
	}
	return nil
}

// misses collects replay misses by kind ("jev", "embed", "review").
type misses struct {
	mu   sync.Mutex
	errs map[string][]string
}

func (m *misses) add(kind string, err error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if m.errs == nil {
		m.errs = map[string][]string{}
	}
	m.errs[kind] = append(m.errs[kind], err.Error())
}

func (m *misses) count(kind string) int {
	m.mu.Lock()
	defer m.mu.Unlock()
	return len(m.errs[kind])
}

// maxMissesShown bounds the misses an error lists.
const maxMissesShown = 3

// check fails on any Jev or embedding miss, and on a review miss unless
// allowed.
func (m *misses) check(allowReview bool) error {
	m.mu.Lock()
	defer m.mu.Unlock()
	var errs []error
	for _, kind := range []string{"jev", "embed", "review"} {
		list := m.errs[kind]
		if len(list) == 0 || (kind == "review" && allowReview) {
			continue
		}
		shown := list[:min(len(list), maxMissesShown)]
		errs = append(errs, fmt.Errorf("quality: %d %s requests have no recording (re-record, or pass -review-misses for reviews): %s",
			len(list), kind, strings.Join(shown, "; ")))
	}
	return errors.Join(errs...)
}

// jevMisses records Jev requests Replay could not serve.
type jevMisses struct {
	next jev.Client
	m    *misses
}

func (j *jevMisses) Evaluate(ctx context.Context, req jev.Request) (jev.Response, error) {
	resp, err := j.next.Evaluate(ctx, req)
	if errors.Is(err, jev.ErrNoRecording) {
		j.m.add("jev", err)
	}
	return resp, err
}

// embedMisses records embedding texts Replay could not serve (the
// pipeline would otherwise quietly skip stage 3).
type embedMisses struct {
	next embed.Embedder
	m    *misses
}

func (e *embedMisses) Model() string { return e.next.Model() }

func (e *embedMisses) Embed(ctx context.Context, texts []string) ([][]float32, error) {
	v, err := e.next.Embed(ctx, texts)
	if errors.Is(err, embed.ErrNoRecording) {
		e.m.add("embed", err)
	}
	return v, err
}

// reviewMisses records review requests Replay could not serve.
type reviewMisses struct {
	next review.Reviewer
	m    *misses
}

func (r *reviewMisses) Model() string { return r.next.Model() }

func (r *reviewMisses) Review(ctx context.Context, req review.Request) (review.Result, error) {
	res, err := r.next.Review(ctx, req)
	if errors.Is(err, review.ErrNoRecording) {
		r.m.add("review", err)
	}
	return res, err
}
